import {parseCSV,csv,qualify,sampleAccounts,transition} from './core.mjs';
import {team} from './team.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;function notify(t){$('#toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',5500);}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
let queue=[];try{const q=JSON.parse(localStorage.getItem('mbm-growth-queue-v1')||'[]');if(Array.isArray(q))queue=q.filter(x=>x&&typeof x.id==='string'&&typeof x.body==='string'&&typeof x.title==='string'&&['draft','approved','rejected'].includes(x.status)).slice(0,100);}catch{}
function saveQueue(){try{localStorage.setItem('mbm-growth-queue-v1',JSON.stringify(queue));}catch{notify('Browser storage unavailable. Export your work before leaving.');}renderQueue();}
function route(){const page=location.hash.slice(1)||'overview';const valid=$(`[data-page="${CSS.escape(page)}"]`)?page:'overview';$$('[data-page]').forEach(e=>e.hidden=e.dataset.page!==valid);$$('[data-nav]').forEach(e=>{e.classList.toggle('active',e.dataset.nav===valid);if(e.dataset.nav===valid)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});window.scrollTo(0,0);document.title=`${valid==='overview'?'Your B2B growth team':({team:'The growth team',research:'Account lab',campaign:'Campaign studio',approvals:'Approval desk',playbooks:'Playbooks',how:'How it works'})[valid]} — MBM Growth OS`;}
window.addEventListener('hashchange',route);route();
function showRole(id){const t=team.find(x=>x.id===id)||team[0];$$('.team-button').forEach(b=>{b.classList.toggle('active',b.dataset.role===t.id);b.setAttribute('aria-pressed',String(b.dataset.role===t.id));});$('#team-detail').innerHTML=`<span class="pill">${esc(t.tag)}</span><h2>${esc(t.name)}</h2><p class="detail-line">${esc(t.line)}</p><div class="detail-block"><h3>What comes in</h3><p>${esc(t.input)}</p></div><div class="detail-block"><h3>What comes out</h3><ul class="outputs">${t.outputs.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></div><div class="detail-block"><h3>How success is measured</h3><p>${esc(t.kpis)}</p></div><div class="detail-block"><h3>Human approval</h3><p>${esc(t.gate)}</p></div><div class="detail-block"><h3>The next handoff</h3><p>${esc(t.handoff)}</p></div><details><summary>View the specialist instruction</summary><p class="prompt">${esc(t.prompt)}</p></details><button class="button" id="role-download">Download role brief ↓</button>`;$('#role-download').onclick=()=>download(`${t.id}-role.md`,roleMarkdown(t));}
$('#team-list').innerHTML=team.map((t,i)=>`<button class="team-button" data-role="${t.id}"><span>${String(i+1).padStart(2,'0')}</span>${esc(t.name)}</button>`).join('');$('#team-list').onclick=e=>{const b=e.target.closest('[data-role]');if(b)showRole(b.dataset.role);};showRole('strategy');
function roleMarkdown(t){return `# ${t.name}\n\n${t.line}\n\n## Inputs\n${t.input}\n\n## Deliverables\n${t.outputs.map(o=>'- '+o).join('\n')}\n\n## KPIs\n${t.kpis}\n\n## Approval\n${t.gate}\n\n## Handoff\n${t.handoff}\n\n## Specialist instruction\n${t.prompt}\n`;}
let accounts=sampleAccounts(),ranked=[],visible=[],page=0;const pageSize=12;let icp={industry:'All',country:'All',min:50,max:500};
function rank(){ranked=accounts.map(a=>qualify(a,icp)).sort((a,b)=>b.score-a.score||a.company.localeCompare(b.company));page=0;renderAccounts();}
function renderAccounts(){const q=$('#account-search').value.toLowerCase();visible=ranked.filter(a=>[a.company,a.industry,a.country].join(' ').toLowerCase().includes(q));const pages=Math.max(1,Math.ceil(visible.length/pageSize));page=Math.min(page,pages-1);$('#accounts-body').innerHTML=visible.slice(page*pageSize,(page+1)*pageSize).map((a,i)=>`<tr><td><strong>${esc(a.company)}</strong><small>${esc(a.country||'Unknown')} · ${esc(a.domain||'No domain supplied')}</small></td><td>${esc(a.industry||'Unknown')}</td><td>${esc(a.employees??'Unknown')}</td><td><span class="score">${a.score}</span></td><td class="signal">${esc(a.signal||'No signal supplied')}</td><td><button class="text-button" data-inspect="${page*pageSize+i}" aria-label="Inspect ${esc(a.company)}">Inspect ↗</button></td></tr>`).join('')||'<tr><td colspan="6">No accounts match this search. Try a broader term or import a list.</td></tr>';$('#account-summary').textContent=`${visible.length} accounts · ${visible.filter(a=>a.score>=80).length} score 80+`;$('#data-source').textContent=accounts[0]?.origin==='Sample · fictional'?'FICTIONAL SAMPLE DATA / all companies and signals are invented':'YOUR IMPORT / information and sources not independently verified';$('#page-label').textContent=`Page ${page+1} of ${pages}`;$('#prev').disabled=page===0;$('#next').disabled=page>=pages-1;$('#export-accounts').disabled=!visible.length;}
$('#icp').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const min=Number(f.get('min')),max=Number(f.get('max'));if(min>max){notify('Minimum employees must be no greater than maximum.');return;}icp={industry:f.get('industry'),country:f.get('country'),min,max};rank();notify('Accounts qualified using the displayed scoring rules.');};$('#account-search').oninput=()=>{page=0;renderAccounts();};$('#prev').onclick=()=>{page--;renderAccounts();};$('#next').onclick=()=>{page++;renderAccounts();};$('#reset-sample').onclick=()=>{accounts=sampleAccounts();$('#account-search').value='';rank();notify('Fictional sample restored.');};
$('#csv-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error('Use a CSV smaller than 1 MB.');const imported=parseCSV(await file.text());if(!imported.length)throw Error('No usable company rows found.');if(imported.length>5000)throw Error('Use 5,000 or fewer unique companies.');accounts=imported;$('#account-search').value='';rank();notify(`Imported ${accounts.length} unique companies. Sources remain unverified.`);}catch(err){notify(err.message);}e.target.value='';};
const headers=['company','domain','industry','country','employees','signal','buyer','source'];$('#template-csv').onclick=()=>download('sample-accounts.csv',csv(sampleAccounts().slice(0,5),headers),'text/csv');$('#export-accounts').onclick=()=>download('qualified-accounts.csv',csv(visible,[...headers,'origin','score','reasons']),'text/csv');
$('#accounts-body').onclick=e=>{const b=e.target.closest('[data-inspect]');if(!b)return;const a=visible[Number(b.dataset.inspect)];$('#record-content').innerHTML=`<h2>${esc(a.company)}</h2><span class="badge">${esc(a.origin)}</span><dl>${[...headers.filter(h=>h!=='company'),'score','reasons'].map(h=>`<dt>${esc(h)}</dt><dd>${esc(a[h]??'Unknown')}</dd>`).join('')}</dl><p class="micro">A supplied source is a reference, not a verification. Check the original before using this account in outreach.</p><button class="button primary" id="use-account">Use in campaign brief →</button>`;$('#record-dialog').showModal();$('#use-account').onclick=()=>{$('#record-dialog').close();$('#campaign-form [name="audience"]').value=`${a.buyer||'Relevant buyer roles'} at ${a.company} (${a.industry||'industry unknown'}, ${a.country||'market unknown'})`;$('#campaign-form [name="evidence"]').value=`${a.origin}. Supplied signal: ${a.signal||'none'}. Source: ${a.source||'not supplied'}. Verify before personalising outreach.`;location.hash='campaign';};};$('#close-dialog').onclick=()=>$('#record-dialog').close();rank();
let currentDraft=null;
$('#campaign-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.meeting&&!/^https?:\/\//i.test(f.meeting)){notify('Use an http or https meeting link.');return;}const isActivation=f.objective==='Customer activation';const body=`CAMPAIGN BRIEF — ${f.business}\nTemplate draft · human review required\n\nOBJECTIVE\n${f.objective} over ${f.horizon}. Agree a numeric target and baseline before launch.\n\nAUDIENCE\n${f.audience}\n\nOFFER\n${f.offer}\n\nSUPPLIED EVIDENCE\n${f.evidence||'None supplied. Validate the audience, problem and proof before making claims.'}\n\nPOSITIONING HYPOTHESIS\nFor ${f.audience}, ${f.business} offers: ${f.offer}\nCheck this message with customer evidence; remove unsupported promises.\n\nCONNECTED EXECUTION PLAN\nWeek 1 — Strategy and research: confirm ICP, exclusions, buyer roles, source dates and current funnel.\nWeek 2 — Brand and studio: validate messaging; prepare an article brief, LinkedIn adaptation, creative brief and relevant landing-page CTA.\nWeek 3 — ${isActivation?'Lifecycle: test end-user onboarding and practical barriers with customer permission.':'Demand generation: review the account shortlist, tailor outreach and align the sales handoff.'}\nWeek 4 — Analytics: compare observed results with the baseline; document stop, iterate or scale decisions. For a longer horizon, repeat after review.\n\nCHANNELS TO VALIDATE\n${isActivation?'Product onboarding, customer email and end-user support.':'Educational LinkedIn content, useful search content and targeted account outreach.'} Paid media is a separate experiment requiring a budget approval.\n\nCONTENT & CREATIVE BRIEF\nTeach one practical solution to the audience’s stated problem. Use the offer as context, a source-backed example as proof and one next step as the CTA. Produce one article, one LinkedIn adaptation and a simple visual explaining the idea.\n\nMEETING-REQUEST DRAFT\nSubject: A conversation about ${f.business}\n\nHi [verified first name],\n\nI’m reaching out from ${f.business}. We work on: ${f.offer}\n\n[Add one verified, relevant reason this may matter to your team. Do not invent a trigger or assume a problem.]\n\nWould a short conversation be useful? ${f.meeting?`You can choose a time here: ${f.meeting}`:'If so, please suggest a convenient time and timezone.'}\n\nBest,\n[Sender name and approved business details]\n[Appropriate preference / opt-out information]\n\nMEASUREMENT\nPrimary outcome: ${f.objective}. Define the denominator, baseline, target, owner and reporting window. Track ${isActivation?'activated end users, time to value and practical adoption barriers':'accepted accounts, positive replies, qualified meetings held and sales-accepted opportunities'}. Do not equate impressions or scheduled meetings with revenue.\n\nAPPROVAL CHECKLIST\nConfirm factual claims and sources; verify recipients and permissions; review brand and assets; check tracking and suppression; approve any spend or public change. Nothing is sent or published from this demo.\n\nHANDOFF\nOwner: [assign]. Reviewer: [assign]. Execution date: [agree]. Return outcomes and exceptions to growth strategy.`;
currentDraft={id:crypto.randomUUID(),title:`${f.business} · ${f.objective}`,body,status:'draft',created:new Date().toISOString()};$('#campaign-output').innerHTML='<span class="step">STRUCTURED TEMPLATE / REVIEW REQUIRED</span><h2>Your connected campaign brief.</h2><pre class="draft-preview"></pre><div class="actions"><button class="button primary" id="to-review">Send to approval desk →</button><button class="button" id="download-draft">Download draft ↓</button></div>';$('.draft-preview').textContent=body;$('#download-draft').onclick=()=>download('campaign-brief.txt',currentDraft.body);$('#to-review').onclick=()=>{if(queue.some(q=>q.id===currentDraft.id)){location.hash='approvals';return;}if(queue.length>=100){notify('Queue limit reached. Export your work and remove old items.');return;}queue.unshift({...currentDraft});saveQueue();location.hash='approvals';notify('Draft added to your local approval desk.');};notify('Campaign template prepared. Review every claim and assumption.');};
function renderQueue(){$('#queue-count').textContent=queue.filter(q=>q.status==='draft').length;$('#approval-list').innerHTML=queue.length?queue.map((q,i)=>`<article class="approval" data-item="${i}"><header><div><h3>${esc(q.title)}</h3><div class="meta">Created ${esc(new Date(q.created).toLocaleString())}${q.updated?' · Updated '+esc(new Date(q.updated).toLocaleString()):''}</div></div><span class="badge ${q.status}">${esc(q.status.toUpperCase())}</span></header><label>Editable campaign draft<textarea class="edit-body" maxlength="20000">${esc(q.body)}</textarea></label><div class="actions"><button class="button" data-action="save">Save edits</button>${q.status==='draft'?'<button class="button primary" data-action="approved">Approve locally ✓</button><button class="button" data-action="rejected">Request changes</button>':'<button class="button" data-action="draft">Return to draft</button>'}<button class="button" data-action="export">Export ↓</button><button class="text-button" data-action="remove">Remove local item</button></div><p class="micro">${q.status==='approved'?'Approved for local handoff only. No external execution occurred.':'Save edits before changing review state.'}</p></article>`).join(''):'<div class="empty"><span class="eyebrow">A CLEAR DESK</span><h2>Good work starts with a brief.</h2><p>Create a campaign, then bring it here to review and approve.</p><a class="button primary" href="#campaign">Create a campaign →</a></div>';$('#export-queue').disabled=!queue.length;}
$('#approval-list').onclick=e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.closest('[data-item]'),i=Number(a.dataset.item),q=queue[i],text=a.querySelector('textarea').value;if(b.dataset.action==='export'){download('campaign-handoff.txt',`Status: ${q.status}\n${q.body}`);return;}if(b.dataset.action==='remove'){if(!confirm('Remove this local draft? Export it first if you need a copy.'))return;queue.splice(i,1);saveQueue();notify('Local item removed.');return;}if(b.dataset.action==='save'){if(!text.trim()){notify('Draft cannot be empty.');return;}queue[i]={...q,body:text,status:'draft',updated:new Date().toISOString()};saveQueue();notify('Edits saved; item is back in draft.');return;}if(text!==q.body){notify('Save your edits before changing the review state.');return;}queue[i]=transition(q,b.dataset.action);saveQueue();notify('Local review status updated. No external action was triggered.');};$('#export-queue').onclick=()=>download('growth-approval-queue.json',JSON.stringify(queue,null,2),'application/json');renderQueue();
const playbooks=team.flatMap(t=>t.outputs.map((name,i)=>({name,t,i})));
function playbookText(p){return `# ${p.name}\n\nRole: ${p.t.name}\n\n## Starting context\n${p.t.input}\n\n## Working instruction\n${p.t.prompt}\n\nFocus this run on: ${p.name}.\n\n## Required output\n1. Goal and scope\n2. Evidence used with source and date\n3. Proposed ${p.name.toLowerCase()}\n4. Assumptions, unknowns and dependencies\n5. Owner, next step and proposed measurement\n\n## Review gate\n${p.t.gate}\nCheck that claims are supported, the intended buyer is clear, and the work answers the approved brief.\n\n## Measurement\n${p.t.kpis}\nChoose the metric relevant to this deliverable; document the baseline, target, denominator and reporting window.\n\n## Handoff\n${p.t.handoff}\n\nThis is a playbook, not proof of execution or an automated integration.\n`;}
function renderPlaybooks(){const q=$('#playbook-search').value.toLowerCase();$('#playbook-list').innerHTML=playbooks.map((p,i)=>({...p,index:i})).filter(p=>(p.name+' '+p.t.name).toLowerCase().includes(q)).map(p=>`<details class="playbook"><summary>${esc(p.name)}</summary><p class="micro">${esc(p.t.name)} / ${esc(p.t.tag)}</p><p>${esc(p.t.input)}</p><p><b>Review:</b> ${esc(p.t.gate)}</p><p><b>Measure:</b> ${esc(p.t.kpis)}</p><button class="button" data-playbook="${p.index}">Download playbook ↓</button></details>`).join('')||'<p>No playbooks found. Try a broader term.</p>';}
$('#playbook-search').oninput=renderPlaybooks;$('#playbook-list').onclick=e=>{const b=e.target.closest('[data-playbook]');if(b){const p=playbooks[Number(b.dataset.playbook)];download(p.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.md',playbookText(p));}};renderPlaybooks();
$('#download-blueprint').onclick=()=>download('mbm-growth-team-blueprint.md','# MBM Growth OS — B2B team blueprint\n\nPublic interactive operating blueprint. Live model, data and execution connections require a separately authorised backend.\n\n'+team.map(roleMarkdown).join('\n---\n\n'));
$('#download-workflow').onclick=()=>download('account-research-workflow.json',JSON.stringify({name:'B2B account research batch',status:'specification-not-connected',trigger:'Owner-approved schedule and timezone',target:200,inputs:['approved ICP','permitted sources','exclusions','freshness window','cost cap'],steps:['collect','normalise domains','deduplicate','enrich with source URLs and observed dates','qualify against ICP','flag unknowns','human verification','sales acceptance','export'],outcomes:['requested','found','qualified','rejected','unresolved'],rules:['No invented fields or contacts','No unauthorised security scanning','Report shortfalls honestly','No outreach before recipient and content approval','Deduplicate by account and run ID before external writes'],productionNeeds:['authenticated users','server-side secrets','licensed data or permitted search','durable queue and retries','persistent evidence and audit log','approved CRM and inbox access','monitoring and spend limits']},null,2),'application/json');
